package com.novasoft.psicoapp.controller;
import com.novasoft.psicoapp.model.*; import com.novasoft.psicoapp.repo.UserRepo; import com.novasoft.psicoapp.service.JwtService; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{ private final UserRepo users; private final PasswordEncoder enc; private final JwtService jwt; public AuthController(UserRepo u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;} public record LoginReq(String email,String password){} public record RegisterReq(@Email String email,String name,String password,Role role){} @PostMapping("/login") public Map<String,Object> login(@RequestBody LoginReq r){User u=users.findByEmail(r.email()).orElseThrow(()->new RuntimeException("Credenciales inválidas")); if(!enc.matches(r.password(),u.password)) throw new RuntimeException("Credenciales inválidas"); return Map.of("token",jwt.generate(u),"user",Map.of("id",u.id,"email",u.email,"name",u.name,"role",u.role));} @PostMapping("/register") public Map<String,Object> register(@RequestBody RegisterReq r){ if(users.findByEmail(r.email()).isPresent()) throw new RuntimeException("El correo ya existe"); User u=new User(); u.email=r.email(); u.name=r.name(); u.password=enc.encode(r.password()); u.role=r.role()==null?Role.ESTUDIANTE:r.role(); users.save(u); return Map.of("id",u.id,"email",u.email,"role",u.role);}}
